// Generated by Cypress Author on 2026-11-26.
// Décrire le scénario de suppression d'un produit depuis la page panier.
describe('Swag Labs cart', () => {
    // Préparer une session utilisateur avant le scénario.
    beforeEach(() => {
        // Se connecter avec la commande partagée.
        cy.login();
        // Ajouter le Sauce Labs Backpack depuis inventory page
        cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').should('be.visible').click();
        // Vérifier que le badge indique un article avant d'ouvrir le panier.
        cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', 1);
        // Naviguer vers la page du panier
        cy.get('[data-test="shopping-cart-link"]').should('be.visible').click();
        // Vérifier que Le navigateur est dirigée vers La page du panier
        cy.location('pathname').should('eq', '/cart.html');
    });

    // Fermer la session après le scénario.
    afterEach(() => {
        // Se déconnecter avec la commande partagée.
        cy.logout();
    });

    // Déclarer le scénario de suppression depuis la page panier à compléter.
    it('supprime un produit depuis la page panier', () => {
        // Cliquer sur le bouton Remove d'un article ajouté au panier
        cy.get('[data-test="remove-sauce-labs-backpack"]').should('be.visible').click();
        // Vérifier que L'article disparaît de la liste
        cy.get('[data-test="item-quantity"]').should('not.exist');
        cy.get('[data-test="inventory-item-name"]').should('not.exist');
        cy.get('[data-test="inventory-item-desc"]').should('not.exist');
        cy.get('[data-test="inventory-item-price"]').should('not.exist');
        // Vérifier que le badge est mis à jour
        cy.get('[data-test="shopping-cart-badge"]').should('not.exist');
    });
});
